document.outline_text:
[
  {
    "intent": "Establish the builder context and explain why decoupling scenario initiation from terminal attachment preserves critical validation evidence.",
    "summary": "I introduce the core operational model defined in docs/TESTING.md, showing how running vrooli scenario test registers the suite with test-genie so that long-running validation remains server-owned rather than vanishing with an agent session.",
    "target_words": 260
  },
  {
    "intent": "Detail the single-block observation pattern that replaces brittle client-side polling loops.",
    "summary": "I walk through capturing the generated run identifier and executing test-genie runs wait --json, detailing why blocking once on a server-owned run delivers reliable evidence across asynchronous operator handoffs.",
    "target_words": 290
  },
  {
    "intent": "Distinguish between client disconnections and intentional test suite termination.",
    "summary": "I examine the failure path where client disconnections are mistaken for suite failures, explaining why test-genie maintains execution until an operator explicitly invokes vrooli scenario test abort.",
    "target_words": 280
  },
  {
    "intent": "Conclude with the systemic value of governed validation records for control-plane reliability.",
    "summary": "I summarize how server-owned runs turn waiting into a durable capability, ensuring that teams make release decisions grounded in verifiable execution history rather than transient infrastructure artifacts.",
    "target_words": 270
  }
]

